test("c1: a capitalised word comes out lower case", () => {
  assert.equal(slugify("Hello"), "hello");
});

test("c1: an all upper-case word comes out lower case", () => {
  assert.equal(slugify("WORLD"), "world");
});

test("c1: mixed case inside a word comes out lower case", () => {
  assert.equal(slugify("camelCaseTitle"), "camelcasetitle");
});

test("c2: a single space between words becomes a dash", () => {
  assert.equal(slugify("hello world"), "hello-world");
});

test("c2: a run of several spaces becomes a single dash", () => {
  assert.equal(slugify("hello   world"), "hello-world");
});

test("c2: every run of spaces between words becomes its own single dash", () => {
  assert.equal(slugify("hello   big world"), "hello-big-world");
});

test("c3: punctuation is removed", () => {
  assert.equal(slugify("hello,world!"), "helloworld");
});

test("c3: an apostrophe and a question mark are removed", () => {
  assert.equal(slugify("what's.up?"), "whatsup");
});

test("c3: accented letters are removed", () => {
  // precomposed é (U+00E9) and ö (U+00F6)
  assert.equal(slugify("héllowörld"), "hllowrld");
});

test('c1: an all upper-case word comes out lower case', () => {
  assert.equal(slugify('HELLO'), 'hello');
});

test('c1: mixed-case letters come out lower case', () => {
  assert.equal(slugify('HeLLoWoRLD'), 'helloworld');
});

test('c2: a single space between words becomes a single dash', () => {
  assert.equal(slugify('hello world'), 'hello-world');
});

test('c2: a run of several spaces between words becomes a single dash', () => {
  assert.equal(slugify('hello    world'), 'hello-world');
});

test('c2: every run of spaces in the title becomes its own single dash', () => {
  assert.equal(slugify('one two   three'), 'one-two-three');
});

test('c3: punctuation is removed', () => {
  assert.equal(slugify('hello,world!'), 'helloworld');
});

test('c3: varied punctuation is removed', () => {
  assert.equal(slugify("what?it's.done:(ok)"), 'whatitsdoneok');
});

test('c3: accented letters are removed', () => {
  // "café" and "naïve" written with precomposed accented letters
  assert.equal(slugify('café'), 'caf');
  assert.equal(slugify('naïve'), 'nave');
});

test("c1: an upper-case first letter comes out lower case", () => {
  assert.equal(slugify("Hello"), "hello");
});

test("c1: an all upper-case title comes out lower case", () => {
  assert.equal(slugify("HELLO"), "hello");
});

test("c1: upper-case letters in the middle of a word come out lower case", () => {
  assert.equal(slugify("helloWorld"), "helloworld");
});

test("c2: a single space between words becomes a single dash", () => {
  assert.equal(slugify("hello world"), "hello-world");
});

test("c2: a run of several spaces between words becomes a single dash", () => {
  assert.equal(slugify("hello   world"), "hello-world");
});

test("c2: every run of spaces in the title becomes its own single dash", () => {
  assert.equal(slugify("hello  big world"), "hello-big-world");
});

test("c3: punctuation is removed", () => {
  assert.equal(slugify("hello,world!"), "helloworld");
});

test("c3: accented letters are removed", () => {
  assert.equal(slugify("héllowörld"), "hllowrld");
});

test("c1: hours followed by minutes are added up in seconds", () => {
  assert.equal(parseDuration("1h30m"), 5400);
});

test("c2: a bare number is seconds", () => {
  assert.equal(parseDuration("90"), 90);
});

test("c3: a part can be a decimal", () => {
  assert.equal(parseDuration("1.5h"), 5400);
});

test("c4: units can be upper case", () => {
  assert.equal(parseDuration("1H30M"), 5400);
});

test("c5: a smaller unit before a larger one is null", () => {
  // Control: the same parts in the right order parse, so null here is about the order.
  assert.equal(parseDuration("1h30m"), 5400);
  assert.equal(parseDuration("30m1h"), null);
});

test("c6: an unknown unit is null", () => {
  // Control: the parser does parse known units, so null here is about the unit.
  assert.equal(parseDuration("1h30m"), 5400);
  assert.equal(parseDuration("1x"), null);
});

test("c1: hours followed by minutes are added up as seconds", () => {
  assert.equal(parseDuration("1h30m"), 5400);
});

test("c2: a bare number with no unit is that many seconds", () => {
  assert.equal(parseDuration("90"), 90);
  assert.equal(parseDuration("45"), 45);
});

test("c3: a decimal part is accepted", () => {
  assert.equal(parseDuration("1.5h"), 5400);
  assert.equal(parseDuration("0.5h"), 1800);
});

test("c4: upper-case unit letters are accepted", () => {
  assert.equal(parseDuration("1H30M"), 5400);
  assert.equal(parseDuration("2H"), 7200);
});

test("c5: units written smaller before larger return null", () => {
  assert.equal(parseDuration("30m1h"), null);
  assert.equal(parseDuration("15s30m"), null);
  assert.equal(parseDuration("15s1h"), null);
});

test("c6: text with an unknown unit returns null", () => {
  assert.equal(parseDuration("1x"), null);
  assert.equal(parseDuration("5q"), null);
});

test("c1: \"1h30m\" returns 5400", () => {
  assert.equal(parseDuration("1h30m"), 5400);
});

test("c2: a bare number with no unit is that many seconds", () => {
  assert.equal(parseDuration("90"), 90);
});

test("c3: a decimal part is accepted, \"1.5h\" returns 5400", () => {
  assert.equal(parseDuration("1.5h"), 5400);
});

test("c4: upper-case unit letters are accepted, \"1H30M\" returns 5400", () => {
  assert.equal(parseDuration("1H30M"), 5400);
});

test("c5: units written smaller before larger return null", () => {
  assert.equal(parseDuration("30m1h"), null);
  assert.equal(parseDuration("30s1m"), null);
  assert.equal(parseDuration("30s1h"), null);
});

test("c6: text with an unknown unit returns null", () => {
  assert.equal(parseDuration("1x"), null);
});
